#include "apk_java_runtime.h"
#include "apk_sha256.h"
#include "../android_java_app/apk_pins.h" /* generated by build_android_java_apks.py */
#include <string.h>

static int find_pin(const char *package_name)
    {
    unsigned i;
    if (!package_name) return -1;
    for (i=0u;i<E63_PIN_COUNT;++i)
        if (strcmp(e63_apk_pins[i].package_name,package_name)==0)
            return (int)i;
    return -1;
    }
const char *e63_session_apk_name(const char *package_name)
    {
    int index=find_pin(package_name);
    return index<0 ? 0 : e63_apk_pins[index].filename;
    }
E63SessionStatus e63_session_open(E63JavaSession *session,
                                   const char *package_name,
                                   const uint8_t *apk, size_t size)
    {
    uint8_t digest[32];
    E63JavaSession result;
    E63DexMethod code;
    int index=find_pin(package_name);
    if (!session || !apk || !size || size>E63_APK_MAX_BYTES)
        return E63_SESSION_INVALID;
    if (index<0) return E63_SESSION_NOT_TRUSTED;
    if (size!=e63_apk_pins[index].length) return E63_SESSION_NOT_TRUSTED;
    e63_apk_sha256(apk,size,digest);
    if (memcmp(digest,e63_apk_pins[index].sha256,32u)!=0)
        return E63_SESSION_NOT_TRUSTED;
    memset(&result,0,sizeof(result));
    if (e63_apk_dex_open(apk,size,&result.dex)!=E63_APK_OK)
        return E63_SESSION_BAD_APK;
    {
    const char *program=e63_apk_pins[index].program;
    size_t len=strlen(program);
    const char *guest="Lorg/e63/dalvik/runtime/GuestActivity;";
    if (len<8u || len-8u+6u>sizeof(result.activity) ||
        strcmp(program+len-8u,"Program;")!=0)
        return E63_SESSION_NO_PROGRAM;
    memcpy(result.activity,program,len-8u);
    memcpy(result.activity+len-8u,"Main;",6u);
    if (!e63_dex_super_is(&result.dex,result.activity,guest) ||
        !e63_dex_super_is(&result.dex,guest,"Landroid/app/Activity;"))
        return E63_SESSION_NO_PROGRAM;
    }
    if (e63_dex_find_code(&result.dex,e63_apk_pins[index].program,
                          "onStart","()V",&code)!=1 ||
        e63_dex_find_code(&result.dex,e63_apk_pins[index].program,
                          "onSelect","(I)V",&code)!=1 ||
        e63_dex_find_code(&result.dex,e63_apk_pins[index].program,
                          "onCommand","(ILjava/lang/String;Ljava/lang/String;)V",&code)!=1 ||
        e63_dex_find_code(&result.dex,result.activity,"<init>","()V",&code)!=1 ||
        e63_dex_find_code(&result.dex,result.activity,"showProgram","()V",&code)!=1 ||
        e63_dex_find_code(&result.dex,result.activity,"selectProgram","(I)V",&code)!=1 ||
        e63_dex_find_code(&result.dex,result.activity,"commandProgram",
                          "(ILjava/lang/String;Ljava/lang/String;)V",&code)!=1 ||
        e63_dex_find_code(&result.dex,"Lorg/e63/dalvik/runtime/GuestActivity;",
                          "<init>","()V",&code)!=1 ||
        e63_dex_find_code(&result.dex,"Lorg/e63/dalvik/runtime/GuestActivity;",
                          "onCreate","(Landroid/os/Bundle;)V",&code)!=1 ||
        e63_dex_find_code(&result.dex,"Lorg/e63/dalvik/runtime/GuestActivity;",
                          "onResume","()V",&code)!=1 ||
        e63_dex_find_code(&result.dex,"Lorg/e63/dalvik/runtime/GuestActivity;",
                          "redraw","()V",&code)!=1 ||
        e63_dex_find_code(&result.dex,"Lorg/e63/dalvik/runtime/GuestActivity;",
                          "choose","(I)V",&code)!=1 ||
        e63_dex_find_code(&result.dex,"Lorg/e63/dalvik/runtime/GuestActivity;",
                          "command","(ILjava/lang/String;Ljava/lang/String;)V",&code)!=1)
        return E63_SESSION_NO_PROGRAM;
    result.apk=apk;
    result.apk_bytes=size;
    result.pin_index=(unsigned)index;
    result.package_name=e63_apk_pins[index].package_name;
    result.program=e63_apk_pins[index].program;
    *session=result;
    return E63_SESSION_OK;
    }
E63JavaStatus e63_session_run(const E63JavaSession *session,
                               const char *name, const char *prototype,
                               const E63JavaValue *arguments, unsigned count,
                               const E63JavaHost *host)
    {
    if (!session || !session->apk || !session->dex.data ||
        session->pin_index>=E63_PIN_COUNT ||
        session->apk_bytes!=e63_apk_pins[session->pin_index].length ||
        session->package_name!=e63_apk_pins[session->pin_index].package_name ||
        session->program!=e63_apk_pins[session->pin_index].program)
        return E63_JAVA_BAD_INPUT;
    return e63_java_run(&session->dex,session->program,name,prototype,
                        arguments,count,host);
    }
int e63_session_owns_asset(const E63JavaSession *session,
                            const char *asset_name)
    {
    unsigned i;
    const E63PinnedApk *pin;
    if (!session || !session->apk || !asset_name ||
        session->pin_index>=E63_PIN_COUNT) return 0;
    pin=&e63_apk_pins[session->pin_index];
    if (session->package_name!=pin->package_name) return 0;
    for (i=0u;i<pin->asset_count;++i)
        if (strcmp(asset_name,pin->assets[i])==0) return 1;
    return 0;
    }
const char *e63_session_status(E63SessionStatus status)
    {
    switch (status) {
        case E63_SESSION_OK:return "built-in APK pin, CRC and DEX verified";
        case E63_SESSION_INVALID:return "invalid APK buffer/size";
        case E63_SESSION_NOT_TRUSTED:return "APK is not an exact built-in SHA-256 pin";
        case E63_SESSION_BAD_APK:return "corrupt APK DEX container";
        case E63_SESSION_NO_PROGRAM:return "missing Java Program code";
        default:return "unknown APK session error";
    }
    }
